const rows = ($input.first().json.data) || [];
const recs = rows.map(r => ({
  rid: r['3'].value,
  exp: r['7'] ? r['7'].value : null,
  vendorId: r['8'] ? r['8'].value : null,
  company: r['9'] ? r['9'].value : '',
  type: r['54'] ? r['54'].value : '',
  stage: (r['152'] && r['152'].value !== null && r['152'].value !== '') ? Number(r['152'].value) : 0,
})).filter(x => x.exp && x.vendorId);

// Renewal supersede: group by vendor+type, keep the NEWEST record (highest id).
const byKey = {};
for (const x of recs) {
  const k = x.vendorId + '|' + x.type;
  if (!byKey[k] || x.rid > byKey[k].rid) byKey[k] = x;
}

const now = new Date();
const today = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const MS = 86400000;
const THRESH = [{stage:1,d:30},{stage:2,d:15},{stage:3,d:7},{stage:4,d:1},{stage:5,d:-1},{stage:6,d:-5}];

const out = [];
for (const x of Object.values(byKey)) {
  const exp = new Date(x.exp + 'T00:00:00Z');
  const daysUntil = Math.round((exp.getTime() - today.getTime()) / MS);
  if (daysUntil > 30 || daysUntil < -10) continue;      // near-term window only
  let dueStage = 0;
  for (const t of THRESH) if (daysUntil <= t.d) dueStage = t.stage;
  if (dueStage > x.stage) {
    out.push({ json: { recordId: x.rid, vendorId: x.vendorId, company: x.company, type: x.type, expiration: x.exp, daysUntil, newStage: dueStage } });
  }
}
return out;

const v = ($input.first().json.data && $input.first().json.data[0]) || {};
const poc = v['28'] ? v['28'].value : '';
const contact = (v['100'] ? v['100'].value : '') || '';
const portal = (v['176'] ? v['176'].value : '') || 'https://vendor-access-lyart.vercel.app/';
const src = $('Compute due').item.json;
const { company, type, expiration, daysUntil, recordId, newStage } = src;

const ERIN = 'erin@excellohomes.com';
const to = [ERIN];
if (poc && /@/.test(poc) && poc.toLowerCase() !== ERIN.toLowerCase()) to.push(poc);

let when;
if (daysUntil > 0) when = 'expires in ' + daysUntil + ' day' + (daysUntil === 1 ? '' : 's');
else if (daysUntil === 0) when = 'expires today';
else { const a = Math.abs(daysUntil); when = 'expired ' + a + ' day' + (a === 1 ? '' : 's') + ' ago'; }

const expNice = new Date(expiration + 'T00:00:00Z').toLocaleDateString('en-US', { year:'numeric', month:'long', day:'numeric', timeZone:'UTC' });
const subject = (daysUntil < 0 ? '[EXPIRED] ' : '[Reminder] ') + type + ' for ' + company + ' ' + when;
const hi = contact ? ('Hi ' + contact + ',') : 'Hello,';
const html =
  '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#222">' +
  '<p>' + hi + '</p>' +
  '<p>This is an automated reminder from Byrdson Services. The following compliance document <b>' + when + '</b>:</p>' +
  '<table cellpadding="6" style="border-collapse:collapse;font-size:14px;margin:8px 0">' +
  '<tr><td style="color:#666">Vendor</td><td><b>' + company + '</b></td></tr>' +
  '<tr><td style="color:#666">Document</td><td>' + type + '</td></tr>' +
  '<tr><td style="color:#666">Expiration date</td><td>' + expNice + '</td></tr>' +
  '</table>' +
  '<p>Please upload the renewed document as soon as possible through your vendor portal:</p>' +
  '<p><a href="' + portal + '" style="background:#1a5fb4;color:#fff;padding:10px 16px;border-radius:6px;text-decoration:none;display:inline-block">Upload updated document</a></p>' +
  '<p style="color:#888;font-size:12px">Once the updated document is uploaded, these reminders stop automatically.</p>' +
  '</div>';

return [{ json: { toList: to.join(','), subject, html, recordId, newStage } }];
